import { test, expect, type Page } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/reg1-r12.json'), colorScheme: 'dark' });

const ownButton = (page: Page) => page.getByRole('button', { name: /הסטורי שלי/ });

// Открыть /discover при заданном окне и дождаться, что кнопка «הסטורי שלי» — верхний элемент в своём центре (ушёл сплэш).
async function openDiscoverAt(page: Page, width: number, height: number) {
  await page.setViewportSize({ width, height });
  await page.goto('/discover');
  const btn = ownButton(page);
  await expect(btn).toBeVisible();
  await expect
    .poll(() =>
      btn.evaluate((el) => {
        const r = el.getBoundingClientRect();
        const top = document.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
        return !!top && el.contains(top);
      }),
    )
    .toBe(true);
}

type Box = { x: number; y: number; width: number; height: number };

// Rect'ы всех нужных элементов одним замером (после отрисовки).
async function measure(page: Page) {
  return page.evaluate(() => {
    const r = (e: Element | null | undefined): Box | null => {
      if (!e) return null;
      const b = e.getBoundingClientRect();
      return { x: b.x, y: b.y, width: b.width, height: b.height };
    };
    const btns = [...document.querySelectorAll('button, [role=button]')];
    const own = btns.find((b) => (b.textContent ?? '').includes('הסטורי שלי') && b.getBoundingClientRect().width < 150)!;
    const label = [...own.querySelectorAll('div')].find((d) => d.childElementCount === 0 && d.textContent?.trim() === 'הסטורי שלי');
    const logo = [...document.querySelectorAll('div')].find((d) => d.childElementCount === 0 && d.textContent === 'MAGNET');
    const byName = (n: string) => btns.find((b) => (b.getAttribute('aria-label') ?? b.textContent ?? '').trim() === n);
    const photo = [...document.querySelectorAll('img')]
      .filter((i) => /\.(jpe?g|webp)/i.test(i.src) && !i.src.includes('/avatars/'))
      .map((i) => ({ i, b: i.getBoundingClientRect() }))
      .filter((o) => o.b.height > 200)
      .sort((a, b) => b.b.width * b.b.height - a.b.width * a.b.height)[0]?.i;
    // Подписи всех кружков ряда (для проверки «не шире колонки» и «не пересекает соседние»).
    const columns = btns
      .filter((b) => b.getBoundingClientRect().top > 40 && b.getBoundingClientRect().top < 130 && !!b.querySelector('img[src*="/avatars/"]'))
      .map((b) => ({
        col: r(b)!,
        label: r([...b.querySelectorAll('div')].filter((d) => d.childElementCount === 0 && (d.textContent ?? '').trim() !== '').pop()),
      }));
    return {
      circle: r(own.querySelector('div')),
      label: r(label),
      logo: r(logo),
      boost: r(byName('להפעיל בוסט')),
      shop: r(byName('חנות')),
      photo: r(photo),
      columns,
    };
  });
}

test.describe('Раунд 13: кружки сторис 62/60/57/52 (#c94032)', () => {
  test('Подпись, шапка и фото карточки не накладываются на ряд @iphone @prod-safe', async ({ page }) => {
    for (const [width, height] of [[390, 844], [375, 812]]) {
      await openDiscoverAt(page, width, height);
      // Ждём, пока фото верхней карточки появится и раскладка перестанет меняться.
      let prev = '';
      await expect
        .poll(async () => {
          const m = await measure(page);
          const cur = JSON.stringify([m.circle, m.label, m.photo]);
          const ok = !!m.photo && cur === prev;
          prev = cur;
          return ok;
        }, { message: `раскладка при ${width}` })
        .toBe(true);

      // 1. На каждой ширине снять rect: подпись, кружок, MAGNET, ⚡, 👑, верх изображения верхней карточки.
      const m = await measure(page);
      const circle = m.circle!, label = m.label!, logo = m.logo!, boost = m.boost!, shop = m.shop!, photo = m.photo!;
      const tag = `при ${width}`;

      // Верх подписи ≥ низ кружка; подпись не шире своей колонки и не пересекает соседние подписи.
      expect(label.y, `верх подписи ≥ низ кружка ${tag}`).toBeGreaterThanOrEqual(circle.y + circle.height - 0.5);
      for (const c of m.columns) {
        if (!c.label) continue;
        expect(c.label.width, `подпись не шире колонки ${tag}`).toBeLessThanOrEqual(c.col.width + 0.5);
      }
      const labels = m.columns.map((c) => c.label!).filter(Boolean).sort((a, b) => a.x - b.x);
      for (let i = 1; i < labels.length; i++) {
        expect(labels[i].x, `подписи не пересекаются ${tag}`).toBeGreaterThanOrEqual(labels[i - 1].x + labels[i - 1].width - 0.5);
      }

      // Низ шапки (⚡, 👑, MAGNET) ≤ верх кружка; ⚡ и 👑 справа от логотипа в одной строке с ним.
      for (const [name, el] of [['MAGNET', logo], ['⚡', boost], ['👑', shop]] as const) {
        expect(el.y + el.height, `низ ${name} ≤ верх кружка ${tag}`).toBeLessThanOrEqual(circle.y + 0.5);
      }
      const rowMid = logo.y + logo.height / 2;
      for (const [name, el] of [['⚡', boost], ['👑', shop]] as const) {
        expect(el.x, `${name} справа от логотипа ${tag}`).toBeGreaterThanOrEqual(logo.x + logo.width - 0.5);
        expect(Math.abs(el.y + el.height / 2 - rowMid), `${name} в одной строке с логотипом ${tag}`).toBeLessThanOrEqual(logo.height);
      }

      // Верх фото карточки ≥ низ подписи + 6.
      expect(photo.y, `верх фото ≥ низ подписи + 6 ${tag}`).toBeGreaterThanOrEqual(label.y + label.height + 6 - 0.5);
    }
  });
});
